    char *str = malloc(size + 1); // +1 for null terminator
    if (!str) {
        // Allocation failed
        return NULL;
    }

    // Copy string data from the byte node
    memcpy(str, *bnode, size);
    str[size] = '\0'; // Null terminate the string

