plist_t parse_string_node(const char **bnode, uint64_t size) {
    char *string_data = malloc(size + 1);
    if (!string_data) {
        return NULL;
    }

    memcpy(string_data, *bnode, size);
    string_data[size] = '\0';

    plist_t node = create_plist_node(PLIST_STRING);
    if (!node) {
        free(string_data);
        return NULL;
    }

    node->data.string = string_data;
    node->length = size;

    return node;
}
